create function public.prohibit_financial_record_delete() returns trigger language plpgsql as $$begin raise exception 'Financial records cannot be deleted.';end$$;
create trigger financial_no_delete before delete on commission_events for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on dancer_payout_batches for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on dancer_payout_items for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on dancer_earning_status_history for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on financial_audit_events for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on nats_commission_exports for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on agent_commission_events for each row execute function prohibit_financial_record_delete();
create trigger financial_no_delete before delete on nats_agent_commission_exports for each row execute function prohibit_financial_record_delete();
create function public.prevent_pickup_history_rewrite() returns trigger language plpgsql as $$begin raise exception 'Pickup history cannot be edited or deleted.';end$$;
create trigger pickup_immutable before update or delete on pickup_messages for each row execute function prevent_pickup_history_rewrite();
create trigger pickup_immutable before update or delete on pickup_events for each row execute function prevent_pickup_history_rewrite();
create trigger pickup_immutable before update or delete on pickup_consents for each row execute function prevent_pickup_history_rewrite();
create trigger pickup_immutable before update or delete on pickup_reports for each row execute function prevent_pickup_history_rewrite();
create trigger pickup_immutable before update or delete on pickup_arrival_evidence for each row execute function prevent_pickup_history_rewrite();
